import {sendEvent} from '@github-ui/hydro-analytics'
import {Button, Heading, Label, Link, Popover} from '@primer/react'
import {useCallback, useEffect, useRef} from 'react'

import {copilotLocalStorage} from '../utils/copilot-local-storage'
import styles from './AgentCapabilitiesPopover.module.css'

const CHANGELOG_URL = 'https://docs.github.com/early-access/github/articles/cca-march-update'

interface AgentCapabilitiesPopoverProps {
  onDismiss: () => void
}

export function AgentCapabilitiesPopover({onDismiss}: AgentCapabilitiesPopoverProps) {
  const shownEventSentRef = useRef(false)

  useEffect(() => {
    if (!shownEventSentRef.current) {
      shownEventSentRef.current = true
      sendEvent('dotcom_chat.activate', {target: 'AGENT_CAPABILITIES_TOOLTIP', action: 'shown'})
    }
  }, [])

  const dismiss = useCallback(() => {
    copilotLocalStorage.setAgentCapabilitiesTooltipDismissed()
    onDismiss()
    sendEvent('dotcom_chat.activate', {target: 'AGENT_CAPABILITIES_TOOLTIP', action: 'dismiss'})
  }, [onDismiss])

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic -- Simple Escape dismiss for non-modal tooltip without Primer Overlay
      if (e.key === 'Escape' && !e.defaultPrevented) {
        onDismiss()
        sendEvent('dotcom_chat.activate', {target: 'AGENT_CAPABILITIES_TOOLTIP', action: 'dismiss_temporary'})
      }
    }

    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [onDismiss])

  return (
    <div className={styles.popoverAnchor}>
      <Popover open caret="top-left" className={styles.popover}>
        <Popover.Content aria-label="New Agent mode">
          <Heading as="h2" variant="small" className={styles.heading}>
            Agent mode
            <Label variant="accent">New</Label>
          </Heading>
          <p className={styles.text}>
            Agents now support a broader set of functionality, like helping you create an implementation plan or
            conducting deep research on a codebase.{' '}
            <Link
              inline
              href={CHANGELOG_URL}
              target="_blank"
              rel="noopener noreferrer"
              onClick={() =>
                sendEvent('dotcom_chat.activate', {target: 'AGENT_CAPABILITIES_TOOLTIP', action: 'read_more'})
              }
            >
              Learn more about Copilot coding agent
            </Link>
          </p>
          <Button size="small" onClick={dismiss}>
            Got it!
          </Button>
        </Popover.Content>
      </Popover>
    </div>
  )
}
